const completeArticleSourceLabels={en:"Published-source context",de:"Kontext der veröffentlichten Quellen",fr:"Contexte des sources publiées",es:"Contexto de fuentes publicadas",it:"Contesto delle fonti pubblicate",pt:"Contexto das fontes publicadas",nl:"Context van gepubliceerde bronnen",pl:"Kontekst opublikowanych źródeł",sv:"Kontext för publicerade källor"};
routePage=function(kind){
 if(kind!=="articles")return completeArticleRoute(kind);
 const article=completeArticles[lang]||completeArticles.en;
 const body=`<article class="article"><p class="article-kicker">${article.readTime} · ${article.wordTarget}</p><h2>${article.title}</h2><p>${article.deck}</p>${article.sections.map((section,index)=>`<section><h3>${index+1}. ${section.heading}</h3>${section.paragraphs.map(paragraph=>`<p>${paragraph}</p>`).join("")}</section>`).join("")}<section><h3>${completeArticleSourceLabels[lang]||completeArticleSourceLabels.en}</h3><ul>${article.sources.map(source=>`<li>${source}</li>`).join("")}</ul></section></article>`;
 return `<section class="route-hero"><div class="shell"><div class="eyebrow">${article.readTime} · ${article.wordTarget}</div><h1>${article.title}</h1><p>${article.deck}</p></div></section><main class="route-main"><div class="shell">${body}</div></main>`;
};
render();
// SEO source is intentionally one fixed, complete English article in every UI language.
// This prevents language switching from selecting a shorter alternative article.
const fixedSeoArticleRoute=routePage;
routePage=function(kind){
  if(kind!=="articles") return fixedSeoArticleRoute(kind);
  return `<section class="route-hero"><div class="shell"><div class="eyebrow">${t.eyebrow}</div><h1>Evidence-led PikoBuy guides</h1><p>A practical guide based on the platform’s published workflow and policy boundaries.</p></div></section><main class="route-main"><div class="shell">${evidenceArticle}</div></main>`;
};
render();
